INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺二年十二月刘言奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-december-952-hunan/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年十二月刘言奏报，段落 jiu-wudaishi-205deb4a7860-p002680；已核上下文及传主，纸本及异文待核。", "id": "ea816b38-74ec-5713-b766-d3cdf7ddf23a"}, {"title": "旧五代史·卷112·太祖本纪三·广顺三年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-january-953-yeji/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺三年正月，段落 jiu-wudaishi-205deb4a7860-p002681；已核上下文及传主，纸本及异文待核。", "id": "2d7ae78a-ac67-562a-aa5e-6b532a2abaee"}, {"title": "旧五代史·卷112·太祖本纪三·广顺二年十一月荆南奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-november-952-hunan/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年十一月荆南奏报，段落 jiu-wudaishi-205deb4a7860-p002679；已核上下文及传主，纸本及异文待核。", "id": "5eb3eaa3-e3ee-586e-95c5-890b977c00aa"}, {"title": "旧五代史·卷112·太祖本纪三·广顺二年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-october-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年十月，段落 jiu-wudaishi-205deb4a7860-p002678；已核上下文及传主，纸本及异文待核。", "id": "13ec6d5a-75da-5285-981d-6a91ed3cc18d"}, {"title": "资治通鉴·卷291·广顺二年十月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/tongjian-291-952-october/source.txt", "note": "《资治通鉴》卷291·广顺二年十月至十二月，段落 zizhi-tongjian-a63549944a71-p003454；已核上下文及传主，纸本及异文待核。", "id": "259474f3-6192-5096-9244-e7a279478f03"}, {"title": "新五代史·卷66·楚世家第六·刘言", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/xinwudaishi-66-liuyan-hunan/source.txt", "note": "《新五代史》卷66·楚世家第六·刘言，段落 xin-wudaishi-b08f244b9241-p003336；已核上下文及传主，纸本及异文待核。", "id": "7fa372db-b289-5dc4-a6d6-ddd3e2c31c64"}, {"title": "新五代史·卷66·楚世家第六·周行逢", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/xinwudaishi-66-zhouxingfeng-hunan/source.txt", "note": "《新五代史》卷66·楚世家第六·周行逢，段落 xin-wudaishi-b08f244b9241-p003340；已核上下文及传主，纸本及异文待核。", "id": "7efb230f-51ab-55d0-b71c-463bb5a37b7e"}, {"title": "资治通鉴·卷291·广顺二年·九月至十月及卷首年界", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0b5d180c84d59cd6b51901d4787f2720c08451e0/content/books/zizhi-tongjian/vol-291/year-0952/part-01/sources/library/tongjian-291-952-september/source.txt", "note": "《资治通鉴》卷291·广顺二年·九月至十月及卷首年界，段落 zizhi-tongjian-a63549944a71-p003453；已核上下文及传主，纸本及异文待核。", "id": "92887882-9d2a-5f18-bb23-0a5e34b539bc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "孙朗", "aliases": ["孫朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原随蒙城镇将咸师朗投降南唐的军人，后任奉节指挥使。南唐取湖南后因功赏和粮赐问题不满，与曹进商议杀王绍颜、边镐，夺取湖南归附中原。实际起事在952年另段，不提前录为951年既成事实。生卒年未载。", "biography": null, "status": "draft", "id": "becfbb42-fad5-53c5-ab22-fbcbaad91d0d"}, {"name": "曹进", "aliases": ["曹進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐奉节指挥使，原随咸师朗降唐。因功赏、粮赐问题，与孙朗商议杀王绍颜和边镐、夺湖南归附中原。此处为计划，实际起事另见952年。生卒年未载。", "biography": null, "status": "draft", "id": "8b8bc9ad-b3fa-5fbf-9fe9-2287b2a8811d"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "郭再诚", "aliases": ["郭再誠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐指挥使。952年十月受边镐派遣率兵驻益阳，抵御朗州军。生卒年未载。", "biography": null, "status": "draft", "id": "8229bffd-88c5-57d8-8cce-132da6ef7451"}, {"name": "刘承遇", "aliases": ["劉承遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐驻沅江都监。952年十月王逵等攻下沅江时被俘。生卒年未载。", "biography": null, "status": "draft", "id": "6377358b-b5f0-577c-960a-a256c9845699"}, {"name": "李师德", "aliases": ["李師德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐裨将。952年十月沅江被攻下时率五百人投降王逵等。生卒年未载。", "biography": null, "status": "draft", "id": "d4968839-21cf-5d41-86f0-3dd1f39cd3b7"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "李建期", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。南唐取湖南以后，受李璟之命驻益阳、谋取朗州，较长时间没有取得成果。生卒年未载。", "biography": null, "status": "draft", "id": "a96853c0-b5fb-55c1-affb-4b16c6ccd874"}, {"name": "廖偃", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "廖匡图之子，楚国衡山指挥使。951年与叔父廖匡凝商议扶助被废的马希萼，率庄户和乡人，与彭师暠共同拥立马希萼为衡山王。生卒年未载。", "biography": null, "status": "draft", "id": "d604ed00-6b4d-52ea-bc7d-00a0c995ff48"}, {"name": "何敬真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武陵人，朗州步军指挥使。950年率部族兵攻破韩礼在杨柳桥的防线；马希萼入长沙后任他为朗州牙内都指挥使，率兵戍守。生卒年未载。", "biography": null, "status": "draft", "id": "0ce9ccfa-b68b-575c-96b0-8022528be7ad"}, {"name": "蒲公益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州牙将。952年与王逵等受刘言任命为指挥使。后文同一行动写薄公益，字形对应待同场回查，未据姓字另造人物。生卒年未载。", "biography": null, "status": "draft", "id": "e6f84c28-a623-5591-99b2-53a8d5d9a4e4"}, {"name": "宋德权", "aliases": ["宋德權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐岳州刺史。952年十月朗州军攻岳州时逃走，《旧五代史》奏报也记其弃城。生卒年未载。", "biography": null, "status": "draft", "id": "6738b76c-5fd8-56f0-ad32-78f77a60f7a9"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "郭彦钦", "aliases": ["郭彥欽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周庆州刺史。《资治通鉴》记其为索取贿赂而侵扰野鸡族，导致当地反抗及商旅遭抢掠。生卒年未载。", "biography": null, "status": "draft", "id": "a5916bd2-ffb5-5cb1-8194-496b8dad0993"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "欧阳广", "aliases": ["歐陽廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉水人。952年上书警告边镐不适合统帅湖南，建议另择将帅、增兵，未获回复。生卒年未载。", "biography": null, "status": "draft", "id": "61774c0b-0f14-586f-8c16-90636b785ac9"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

